//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::string::memcmp`; the
//! native twin is `benches/native/Bench/StringMemcmp.lean`.
//! both sides make the program's tests that supply the proofs; Lean's Array.get! retains and
//! releases the string it reads (an increment and a decrement of its count); the Rust side
//! borrows it

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::string;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &Vec<String>, n: u64) -> u64 {
    let ss = &inp[..];
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let (a, b) = (get_str(ss, x >> 60), get_str(ss, (x >> 56) & 15));
            let l = x & 63;
            if l + 512 <= a.len() as u64 && l + 512 <= b.len() as u64 {
                string::memcmp(a, b, l, l, 512) as u64
            } else {
                0
            }
        });
    }
    acc
}

fn main() {
    run(|| variants(), kernel)
}
